style.css:
@-moz-document domain("music.yandex.ru") {
:root,
    .theme_default,
    .theme_light,
    .theme_dark,
    .page,
    body {
        background-color: #0a0a0f !important;
    }

    /* Глобальные CSS-переменные */
    :root {
        --color-bg-base: #0a0a0f !important;
        --color-bg-container: #14141a !important;
        --color-bg-card: #1c1c24 !important;
        --color-bg-overlay: rgba(10, 10, 15, 0.95) !important;
        --color-bg-popup: #1c1c24 !important;
        
        --color-text-primary: #f0f0f5 !important;
        --color-text-secondary: #a0a0b0 !important;
        --color-text-accent: #c084fc !important;
        --color-text-accent-darker: #9b4dff !important;
        
        --color-accent: #9b4dff !important;
        --color-accent-hover: #b87cff !important;
        --color-border: #2a2a35 !important;
        
        --color-player-bg: #0a0a0f !important;
        --color-sidebar-bg: #0a0a0f !important;
        
        --color-scrollbar-thumb: #4a4a5a !important;
        --color-scrollbar-track: #1c1c24 !important;
    }

    /* Основные блоки */
    .page,
    .d-page,
    .d-layout__content,
    .d-sidebar,
    .d-player,
    .d-header,
    .d-queue,
    .d-playlist,
    .d-album,
    .d-track,
    .d-button,
    .d-input {
        background-color: var(--color-bg-base) !important;
        color: var(--color-text-primary) !important;
    }

    /* Карточки, контейнеры */
    .d-card,
    .d-queue-track,
    .d-playlist-item,
    .d-album__item,
    .d-track__info,
    .d-popup__content,
    .d-context-menu,
    .d-dropdown,
    .d-balloon {
        background-color: var(--color-bg-card) !important;
        border-color: var(--color-border) !important;
        color: var(--color-text-primary) !important;
    }

    /* Текст */
    .d-track__title,
    .d-track__artists,
    .d-sidebar__item,
    .d-queue-track__title,
    .d-queue-track__artists,
    h1, h2, h3, h4, span, p, a, div {
        color: var(--color-text-primary) !important;
    }

    .d-track__artists,
    .d-queue-track__artists,
    .d-text_secondary,
    .d-caption {
        color: var(--color-text-secondary) !important;
    }

    /* Акцентные элементы (кнопки, ссылки) */
    a,
    .d-link,
    .d-button_view_default,
    .d-button_view_raised,
    .d-menu__item_active,
    .d-icon,
    svg path,
    .d-track__like_icon,
    .d-player-controls__button_icon {
        color: var(--color-accent) !important;
        fill: var(--color-accent) !important;
    }

    a:hover,
    .d-link:hover,
    .d-button_view_default:hover,
    .d-button_view_raised:hover {
        color: var(--color-accent-hover) !important;
        fill: var(--color-accent-hover) !important;
    }

    /* Плеер */
    .d-player,
    .d-player-controls,
    .d-player__controls {
        background-color: var(--color-player-bg) !important;
        border-top-color: var(--color-border) !important;
    }

    /* Ползунки прогресса и громкости */
    .d-progress__bar,
    .d-volume-bar__line {
        background-color: #2a2a35 !important;
    }
    .d-progress__filled,
    .d-volume-bar__filled,
    .d-progress__line_filled,
    .d-volume-bar__line_filled {
        background-color: var(--color-accent) !important;
    }

    /* Кнопки управления плеером */
    .d-player-controls__button_play svg,
    .d-player-controls__button_next svg,
    .d-player-controls__button_prev svg {
        fill: var(--color-text-primary) !important;
    }

    /* Поле поиска, инпуты */
    .d-input__control,
    .d-search__input,
    input[type="text"],
    input[type="search"],
    textarea {
        background-color: var(--color-bg-container) !important;
        border-color: var(--color-border) !important;
        color: var(--color-text-primary) !important;
    }

    /* Скроллбар */
    ::-webkit-scrollbar {
        width: 8px;
        height: 8px;
    }
    ::-webkit-scrollbar-track {
        background: var(--color-scrollbar-track);
    }
    ::-webkit-scrollbar-thumb {
        background: var(--color-scrollbar-thumb);
        border-radius: 4px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: var(--color-accent);
    }
}
